import React from 'react';
import styled from 'styled-components';
import { FaAngleDown } from 'react-icons/fa';

import { useSpring, animated, config } from "react-spring";
import Brand from './Brand';

const NavBar = (props) => {

    const { goTo } = props

    const barAnimation = useSpring({
        from: { transform: 'translate3d(0, -10rem, 0)' },
        transform: 'translate3d(0, 0, 0)',
    });

    const linkAnimation = useSpring({
        from: { transform: 'translate3d(0, 30px, 0)', opacity: 0 },
        to: { transform: 'translate3d(0, 0, 0)', opacity: 1 },
        delay: 800,
        config: config.wobbly,
    });

    const HooverMenu = () => {

        return (
            <Menu>
                <MenuItem onClick={() => goTo('services1')}>
                    <MenuLink>Ryczałt od przychodów ewidencjonalnych</MenuLink>
                </MenuItem>
                <MenuItem onClick={() => goTo('services2')}>
                    <MenuLink>Podatkowa książka przychodów i rozchodów</MenuLink>
                </MenuItem>
                <MenuItem onClick={() => goTo('services3')}>
                    <MenuLink>Księgi handlowe</MenuLink>
                </MenuItem>
                <MenuItem>
                    <MenuLink onClick={() => goTo('services4')}>Kadry i płace</MenuLink>
                </MenuItem>
            </Menu>
        );
    }

    return (
        <>
            <Navbar style={barAnimation}>
                <FlexContainer>
                    <Brand />
                    <NavLinks style={linkAnimation}>
                        <NavItem>
                            <NLink>oferta <FaAngleDown /></NLink>
                            <HooverMenu />
                        </NavItem>
                        <NavItem>
                            <NLink onClick={() => goTo('about')}>o nas</NLink>
                        </NavItem>
                        <NavItem>
                            <NLink onClick={() => goTo('contact')}>kontakt</NLink>
                        </NavItem>
                    </NavLinks>
                </FlexContainer>
            </Navbar>
        </>
    );
}



export default NavBar


const Menu = styled.ul`
    list-style-type: none;
    display: none;
    position: absolute;
    top: 80%;
    left: 30px;
    background-color: #fff;
    width: 350px;
    padding-top: 25px;
    padding-bottom: 10px;
    border-radius: 25px;
    border: 3px solid #D5992E;
    box-shadow: -10px 10px #D5992E;
`;

const MenuLink = styled.a`
    border-bottom: 1px solid #000;
    color: #000;
    text-decoration: none;
    border: none;
    font-family: 'Source Sans Pro';
    font-weight: normal;
    text-transform: none;
`;

const MenuItem = styled.li`
    padding-left: 1rem;
    padding-bottom: 1rem;
    text-align: left;
    &:hover ${MenuLink} {
        font-weight: bold;
    }
`;


const Navbar = styled(animated.nav)`
    position: fixed;
    width: 100%;
    top: 0;
    left: 0;
    background: #ffffff;
    z-index: 1;
    font-size: 1rem;
`;

const FlexContainer = styled.div`
    max-width: 120rem;
    display: flex;
    margin: auto;
    padding: 0 3rem;
    justify-content: space-between;
    height: 6.5rem;
`;

const NavLinks = styled(animated.ul)`
    display: flex;
    height: 100%;
    justify-self: end;
    list-style-type: none;
    margin: auto 0;
`;

const NLink = styled.a`
    color: #000;
    text-decoration: none;
`;

const NavItem = styled.li`
    height: 100%;
    text-transform: uppercase;
    font-weight: 700;
    border: none;
    transition: all 300ms linear 0s;
    cursor: pointer;
    display: inline-block;
    padding-top: 2.5rem;
    padding-left: 3rem;
    &:hover ${Menu} {
        display: block;
    }
    &:hover ${NLink} {
        color: #D5992E;
    }
`;
